   102	    /// <summary>La combinaison exacte qui compte le moins de billets, ou <c>null</c>.</summary>
   103	    private static NoteCounts? FewestNotes(int amount, NoteCounts available)
   104	    {
   105	        NoteCounts? best = null;
   106	        for (var fifties = 0; fifties <= available.Fifties && fifties * 50 <= amount; fifties++)
   107	        {
   108	            for (var twenties = 0; twenties <= available.Twenties && fifties * 50 + twenties * 20 <= amount; twenties++)
   109	            {
   110	                var rest = amount - fifties * 50 - twenties * 20;
   111	                if (rest % 10 != 0 || rest / 10 > available.Tens)
   112	                {
   113	                    continue;
   114	                }
   115	
   116	                var candidate = new NoteCounts(fifties, twenties, rest / 10);
   117	                if (best is not { } current || candidate.Total < current.Total)
   118	                {
   119	                    best = candidate;
   120	                }
   121	            }
   122	        }
   123	
   124	        return best;
   125	    }
   126	
   127	    /// <summary>Découpe une combinaison en passages d'au plus <see cref="MaxNotesPerPass"/> billets.</summary>
   128	    private static IEnumerable<NoteCounts> Passes(NoteCounts notes)
   129	    {
   130	        var remaining = notes;
   131	        while (remaining.Total > 0)
   132	        {
   133	            var room = MaxNotesPerPass;
   134	            var fifties = Math.Min(room, remaining.Fifties);
   135	            room -= fifties;
   136	            var twenties = Math.Min(room, remaining.Twenties);
   137	            room -= twenties;
   138	            var tens = Math.Min(room, remaining.Tens);
   139	
   140	            var pass = new NoteCounts(fifties, twenties, tens);
   141	            remaining -= pass;
   142	
   143	            yield return pass;
   144	        }
